/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_general_ci */ ;
DELIMITER ;;
CREATE DEFINER=`mtik`@`31.135.199.%` PROCEDURE `getSongsFromGame`(IN game_title varchar(64))
BEGIN
select * from song s where id in
(select song_id from song_subgroup ss where subgroup_id in 
(select id from subgroup sg where group_id in
(select id from maingroup mg where game_id in 
(select id from game g where g.gametitle like concat('%',game_title)
)
)
)
);
END ;;
DELIMITER ;
