/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_general_ci */ ;
DELIMITER ;;
CREATE DEFINER=`mtik`@`31.135.199.%` PROCEDURE `getSongSubgroupsFromGame`(IN game_short varchar(128))
BEGIN
select ss.id, s.officialdisplayband, s.officialdisplaytitle, ss.`position`, ss.src_id, ss.filename 
from song_subgroup ss join song s on s.id=ss.song_id 
where ss.subgroup_id in 
(select sg.id from subgroup sg where sg.group_id in
(select mg.id from maingroup mg where mg.game_id in
(select g.id from game g where gameshort = game_short)
)
) order by s.officialdisplayband, s.officialdisplaytitle;
END ;;
DELIMITER ;
